#!/usr/bin/env python3
"""Apply this milestone's settings to a runner generated by Flutter itself."""
import json
from pathlib import Path
import plistlib
import re
import shutil
import sys

BUNDLE_ID = 'com.techterrain.docdiary.ios'


def configure(root: Path) -> None:
    runner = root / 'ios/Runner'
    project = root / 'ios/Runner.xcodeproj/project.pbxproj'
    info_path = runner / 'Info.plist'
    if not project.is_file() or not info_path.is_file():
        raise RuntimeError('Generate the iOS runner with bootstrap_ios.sh first.')
    with info_path.open('rb') as stream:
        base = plistlib.load(stream)
    base['CFBundleDisplayName'] = 'DocDiary'
    base['LSApplicationQueriesSchemes'] = sorted(set(base.get('LSApplicationQueriesSchemes', []) + ['mailto']))
    base['UISupportedInterfaceOrientations'] = ['UIInterfaceOrientationPortrait']
    base['UISupportedInterfaceOrientations~ipad'] = [
        'UIInterfaceOrientationPortrait', 'UIInterfaceOrientationPortraitUpsideDown',
        'UIInterfaceOrientationLandscapeLeft', 'UIInterfaceOrientationLandscapeRight']

    # The legacy servers are HTTP. Development is explicit; release stays strict.
    for name, allow_http in [('Info-Debug.plist', True), ('Info-Release.plist', False)]:
        values = dict(base)
        values['NSAppTransportSecurity'] = {'NSAllowsArbitraryLoads': allow_http}
        with (runner / name).open('wb') as stream:
            plistlib.dump(values, stream, sort_keys=False)

    with (runner / 'Runner.entitlements').open('wb') as stream:
        plistlib.dump({'keychain-access-groups': []}, stream)

    text = project.read_text()
    pattern = re.compile(r'(?m)^\t\t[A-F0-9]+ /\* (Debug|Profile|Release) \*/ = \{\n.*?^\t\t\};', re.S)
    changed = set()

    def patch_block(match):
        config = match.group(1)
        block = match.group(0)
        if not re.search(r'INFOPLIST_FILE\s*=', block):
            return block
        # Avoid the separate RunnerTests target.
        if 'Runner/Info' not in block:
            return block
        info = 'Info-Debug.plist' if config == 'Debug' else 'Info-Release.plist'
        block = re.sub(r'INFOPLIST_FILE\s*=\s*[^;]+;', f'INFOPLIST_FILE = "Runner/{info}";', block)
        block = re.sub(r'PRODUCT_BUNDLE_IDENTIFIER\s*=\s*[^;]+;', f'PRODUCT_BUNDLE_IDENTIFIER = {BUNDLE_ID};', block)
        if 'CODE_SIGN_ENTITLEMENTS' not in block:
            block = block.replace('buildSettings = {', 'buildSettings = {\n\t\t\t\tCODE_SIGN_ENTITLEMENTS = Runner/Runner.entitlements;', 1)
        changed.add(config)
        return block

    text = pattern.sub(patch_block, text)
    if changed != {'Debug', 'Profile', 'Release'}:
        raise RuntimeError('The Flutter Xcode template changed. No project settings were written; review configure_ios.py.')
    text = re.sub(r'IPHONEOS_DEPLOYMENT_TARGET\s*=\s*([\d.]+);',
                  lambda m: f'IPHONEOS_DEPLOYMENT_TARGET = {max(float(m[1]), 15.0):.1f};', text)
    project.write_text(text)

    podfile = root / 'ios/Podfile'
    if podfile.is_file():
        pod_text = podfile.read_text()
        if re.search(r'(?m)^#?\s*platform :ios,', pod_text):
            pod_text = re.sub(r"(?m)^#?\s*platform :ios,.*$", "platform :ios, '15.0'", pod_text)
        else:
            pod_text = "platform :ios, '15.0'\n" + pod_text
        podfile.write_text(pod_text)

    appicons = runner / 'Assets.xcassets/AppIcon.appiconset'
    contents = appicons / 'Contents.json'
    if contents.is_file():
        icon = root / 'assets/images/app_icon_1024.png'
        # Xcode accepts a single 1024px universal icon in current templates.
        shutil.copy2(icon, appicons / 'DocDiary-1024.png')
        contents.write_text(json.dumps({'images': [{'filename': 'DocDiary-1024.png',
            'idiom': 'universal', 'platform': 'ios', 'size': '1024x1024'}],
            'info': {'author': 'xcode', 'version': 1}}, indent=2) + '\n')
    print('Configured DocDiary: iOS 15+, Keychain, original app icon, Debug HTTP, strict Release networking.')


if __name__ == '__main__':
    configure(Path(sys.argv[1]).resolve())

